insert into products (slug, name, category, description, images, active) values ('hbelt-tg', 'Ceinture sans boucle en cuir', null, 'Découvrez la H-Flex Belt™, la ceinture révolutionnaire sans boucle qui vous offre confort et liberté totale. Fini la douleur au ventre, fini la boucle qui gêne : ◈ Confort absolu : fini la boucle qui rentre dans le ventre ◈ Ultra simple à utiliser : crochet + Velcro → prêt en 10 secondes ◈ Maintien parfait : votre pantalon reste en place toute la journée ◈ Unisexe & Taille Unique : s’adapte à toutes les morphologies', '["/assets/shopify/5caa263001.jpg","/assets/shopify/f7dad11937.jpg","/assets/shopify/99c5da2d8a.png","/assets/shopify/8203d9b21a.png","/assets/shopify/cb4c76b259.png","/assets/shopify/f6d1386a65.jpg"]'::jsonb, true) on conflict (slug) do update set name = excluded.name, category = excluded.category, description = excluded.description, images = excluded.images, active = excluded.active;
