insert into products (slug, name, category, description, images, active) values ('tomi-dynasty-t106', 'Montre à double cadran', null, 'L''élégance ne fait pas de bruit. Elle se remarque. Vous n''avez pas besoin d''une montre à plusieurs centaines d''euros pour avoir de l''allure. La TOMI Dynasty™ T106 combine un design moderne, un cadran ajouré fascinant et une finition haut de gamme qui donnent immédiatement une impression de prestige. ◈ Design premium ◈ Style minimaliste et moderne ◈ Détails inspirés de l''horlogerie de luxe ◈ Mouvement Quartz de haute précision', '["/assets/shopify/72b3da1141.jpg","/assets/shopify/254db3f2b4.jpg","/assets/shopify/19f0421bc1.jpg","/assets/shopify/3d2ad26a1f.jpg","/assets/shopify/424eadecea.jpg","/assets/shopify/c403db6705.jpg","/assets/shopify/8961973d53.jpg"]'::jsonb, true) on conflict (slug) do update set name = excluded.name, category = excluded.category, description = excluded.description, images = excluded.images, active = excluded.active;
