insert into products (slug, name, category, description, images, active) values ('ceinture-aurion', 'Ceinture automatique en cuir', null, 'Changez votre façon de porter une ceinture Une ceinture traditionnelle vous oblige à choisir entre plusieurs trous fixes. Trop serrée après un repas ? Trop lâche pendant la journée ? Ce problème appartient désormais au passé. ◈ Ajustement précis au millimètre près ◈ Design moderne et minimaliste ◈ Facile à mettre et à retirer ◈ Convient aux tenues professionnelles comme décontractées', '["/assets/shopify/95c276eb5e.jpg","/assets/shopify/9206606b7f.jpg","/assets/shopify/f43eec11b2.png","/assets/shopify/9ed55e956b.jpg","/assets/shopify/da5bc4c89d.png","/assets/shopify/32d6a42ecb.png","/assets/shopify/ee2dc27f8d.jpg"]'::jsonb, true) on conflict (slug) do update set name = excluded.name, category = excluded.category, description = excluded.description, images = excluded.images, active = excluded.active;
