insert into products (slug, name, category, description, images, active) values ('vaultpop', 'Portefeuille RFID pop-up', null, 'Ultra fin. Ultra pratique. Ultra sécurisé. Vous en avez assez des portefeuilles épais et désordonnés ? VaultPop™ combine un design moderne en aluminium, un accès instantané à vos cartes et une protection RFID pour garder vos données en sécurité au quotidien. ◈ Jusqu’à 15 cartes + billets ◈ Système pop‑up ◈ Protection RFID intégrée ◈ Design ultra fin', '["/assets/shopify/add26b4fcb.jpg","/assets/shopify/a967d1ba9c.png","/assets/shopify/240dc984db.jpg","/assets/shopify/b44bc5d92e.jpg","/assets/shopify/60832ab066.jpg","/assets/shopify/3b9739aa84.jpg","/assets/shopify/f20d75d096.jpg"]'::jsonb, true) on conflict (slug) do update set name = excluded.name, category = excluded.category, description = excluded.description, images = excluded.images, active = excluded.active;
