insert into products (slug, name, category, description, images, active) values ('cotonpur', 'Pack de 3 boxers coton', null, 'Redécouvrez le Vrai Confort avec le Boxer CotonPur Vous en avez assez des sous-vêtements qui irritent, retiennent la chaleur et se déforment ? Passez au niveau supérieur avec les boxers CotonPur™. Conçus avec un coton de première qualité, ils offrent une douceur inégalée, une respirabilité optimale et une durabilité exceptionnelle. ◈ 🌿 100% Coton Respirant ◈ 🛡️ Anti-Irritations & Hypoallergénique ◈ 💪 Durabilité Exceptionnelle ◈ ✨ Coupe Parfaite & Discrétion', '["/assets/shopify/150107539e.jpg","/assets/shopify/2c4120c53c.jpg","/assets/shopify/639324fadb.jpg","/assets/shopify/cec81e5f75.jpg","/assets/shopify/613861a928.jpg","/assets/shopify/437992ba18.png"]'::jsonb, true) on conflict (slug) do update set name = excluded.name, category = excluded.category, description = excluded.description, images = excluded.images, active = excluded.active;
