insert into products (slug, name, category, description, images, active) values ('arctic-vector', 'Sacoche bandoulière', null, 'Élevez Votre Quotidien avec Style et Fonctionnalité Découvrez l''Arctic Vector™, bien plus qu''une simple sacoche : c''est le compagnon idéal de l''homme moderne, conçu pour allier élégance avant-gardiste et performance inégalée. ◈ Protection Contre les Intempéries ◈ Design Minimaliste, Impact Maximal ◈ Organisation Intuitive et Optimisée ◈ Légèreté et Durabilité', '["/assets/shopify/ba5c93a7e7.jpg","/assets/shopify/69e3b491c2.jpg","/assets/shopify/812b49edd5.jpg","/assets/shopify/f6d872bd2e.jpg","/assets/shopify/022fa76611.jpg"]'::jsonb, true) on conflict (slug) do update set name = excluded.name, category = excluded.category, description = excluded.description, images = excluded.images, active = excluded.active;
