insert into products (slug, name, category, description, images, active) values ('born-pretty-kit', 'Born Pretty – Kit Polygel Professionnel pour Ongles avec Lampe UV/LED – Gel d''Extension 15 ml', null, 'Le kit pour ongles le plus complet pour faire ses ongles a la maison. Découvrez le Kit Polygel BORN PRETTY, une solution tout-en-un pour créer des ongles tendances, résistants et d’aspect professionnel à domicile ou en salon. Idéal pour les débutants comme pour les pro. ◈ Facile à utiliser – modèle le gel sans coulure ◈ Finition professionnelle – effet gel brillant ◈ Kit complet – tout ce dont vous avez besoin inclus ◈ Résultats longue tenue – jusqu’à plusieurs semaines', '["/assets/shopify/c8747ce7d9.jpg","/assets/shopify/49ab32308c.jpg","/assets/shopify/222291e3f9.jpg","/assets/shopify/495cde520b.jpg","/assets/shopify/5bb732c665.jpg","/assets/shopify/9c33e497c2.jpg"]'::jsonb, false) on conflict (slug) do update set name = excluded.name, category = excluded.category, description = excluded.description, images = excluded.images, active = excluded.active;
